#define FOR(i,l,r) for(int i = (l);i < (r);i++)
#define ALL(x) (x).begin(),(x).end()
template<typename T> bool chmax(T& a,const T& b){return a < b ? (a = b,true) : false;}
template<typename T> bool chmin(T& a,const T& b){return b < a ? (a = b,true) : false;}
typedef long long ll;

ll P, K;
bool visitedFlag[1000000];
const ll MOD = 1e9 + 7;

void depthFirstSearch(ll current)
{
	if(visitedFlag[current]) return;
	visitedFlag[current] = true;
	depthFirstSearch(current * K % P);
}

int main()
{
	cin >> P >> K;
	ll totalWays = 1;
	if(K == 1){
		totalWays = (totalWays * P) % MOD;
	}
	for(ll i = 1; i < P; i++) {
		if(!visitedFlag[i]){
			depthFirstSearch(i);
			totalWays = (totalWays * P) % MOD;
		}
	}
	cout << totalWays << "\n";
	return 0;
}
